#!/usr/bin/env python3
"""Re-verify the 3-D free-surface registry rows after the #128 merge.

The merge unions two independent registry contributions:

  * ``main``   : rows for the floating-hemisphere (group ``hulme_hemisphere``),
                 submerged-sphere (``submerged_sphere``) and irregular-frequency
                 (``hulme_chief``) benchmarks, with the reference data quoted
                 from ``docs/marine_bem_benchmarks.md`` tables 10-11;
  * ``m3181``  : rows generated by ``_free_surface_3d_rows()`` (groups
                 ``hulme3d``, ``hulme3d_chief``, ``wang_linton3d``).

Both families are solved by the *same* solver modules (which main also touched:
``free_surface_solver3d.py``, ``symmetry3d.py``).  This script re-runs the
declared-number audit for exactly those groups against the merged tree and
writes the per-row deviation to JSON - i.e. it answers "does the union still
reproduce both sides' declared numbers?" rather than only "do the tests pass".

usage: registry_audit.py <out.json>
"""
from __future__ import annotations

import json
import sys
import time
from pathlib import Path

from tensorbem.benchmarks.declared_numbers import DECLARED_NUMBERS, check

GROUPS = (
    "hulme_hemisphere",
    "submerged_sphere",
    "hulme_chief",
    "hulme3d",
    "hulme3d_chief",
    "wang_linton3d",
)


def main(out: str) -> int:
    entries = [e for e in DECLARED_NUMBERS if e.group in GROUPS]
    print(f"{len(entries)} registry rows in {len(GROUPS)} groups", flush=True)
    t0 = time.time()
    report = check(("fast", "standard", "heavy"), entries=entries)
    report["wall_seconds"] = round(time.time() - t0, 1)
    Path(out).write_text(json.dumps(report, indent=1))
    rows = report["checks"]
    # ``wang_linton_rotational_added_mass_max_ratio_20`` declares a 1e-20
    # numerical floor, so a deviation of exactly -1 there is a sentinel, not a
    # physical mismatch; report both with and without the floor row.
    finite = [r for r in rows if abs(r["declared"]) > 1e-12]
    worst = max(finite, key=lambda r: abs(r["relative_deviation"]))
    print(json.dumps(
        {
            "rows": len(rows),
            "pass": sum(1 for r in rows if r["verdict"] == "PASS"),
            "drift": [r["key"] for r in rows if r["verdict"] != "PASS"],
            "worst_key": worst["key"],
            "worst_relative_deviation": worst["relative_deviation"],
            "worst_tolerance": worst["tolerance"],
            "floor_rows": [r["key"] for r in rows if abs(r["declared"]) <= 1e-12],
            "wall_seconds": report["wall_seconds"],
        },
        indent=1,
    ))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1] if len(sys.argv) > 1 else "registry_audit.json"))